using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> returned type: {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): probe without throwing ---

// 2a. Default resolver knows about Person → succeeds
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? found))
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded: {found!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<Person> returned false");

// 2b. Source-gen context that only covers Person → Widget is unknown
var limited = new JsonSerializerOptions { TypeInfoResolver = PersonOnlyContext.Default };

if (limited.TryGetTypeInfo<Widget>(out JsonTypeInfo<Widget>? widgetInfo))
    Console.WriteLine($"TryGetTypeInfo<Widget> succeeded: {widgetInfo!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<Widget> returned false (no metadata for Widget)");

// --- types ---
public record Person(string Name, int Age);
public record Widget(string Label);

[JsonSerializable(typeof(Person))]
public partial class PersonOnlyContext : JsonSerializerContext;

